(() => {
'use strict';
const client=window.kcSupabase, auth=client&&client.auth, $=s=>document.querySelector(s);
const S={user:null,view:'overview',selectedEvent:null,events:[],announcements:[],members:[],featureItems:{},roster:null,rosterEvent:'',error:''};
function withTimeout(promise,ms,label){let timer;return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(label||'Request timed out. Check your connection and retry.')),ms);})]).finally(()=>clearTimeout(timer));}
async function rpc(name,args){return withTimeout(client.rpc(name,args),12000,'The crew service is taking too long. Check your connection and retry.');}
const role=r=>({super_admin:'Super Admin',admin:'Admin',member:'Member'}[r]||'Member');
const admin=()=>S.user&&S.user.role!=='member', superadmin=()=>S.user&&S.user.role==='super_admin';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=s=>String(s||'KC').trim().split(/\s+/).map(p=>p[0]||'').join('').slice(0,2).toUpperCase()||'KC';
const dt=s=>{let d=new Date(s);return Number.isNaN(+d)?'Date TBA':d.toLocaleString([],{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});};
const ds=s=>{let d=new Date(s);return Number.isNaN(+d)?'TBA':d.toLocaleDateString([],{month:'short',day:'2-digit'});};
async function api(path,method='GET',body){
 if(!client)throw Error(window.KC_CONFIG_ERROR||'Supabase is not configured.');
 const url=new URL(path,location.href);
 const action=url.pathname.split('/').filter(Boolean).pop();
 const payload={...(body||{})};
 if(action==='attendance'&&url.searchParams.has('eventId'))payload.eventId=url.searchParams.get('eventId');
 if(action==='profile'&&method==='PATCH'){const {data,error}=await rpc('crew_update_profile',{p_name:payload.name,p_bio:payload.bio||'',p_avatar_url:payload.avatar_url||null});if(error)throw Error(error.message||'Profile update failed.');return data;}
 const rpcMap={'qr-attendance':['crew_mark_qr_attendance',{p_event_id:payload.eventId,p_member_email:payload.memberEmail}],'finalize-attendance':['crew_finalize_attendance',{p_event_id:payload.eventId}],'delete-event':['crew_delete_event',{p_event_id:payload.eventId}]};
 if(rpcMap[action]){const {data,error}=await rpc(rpcMap[action][0],rpcMap[action][1]);if(error)throw Error(error.message||'Crew operation failed.');return data;}
 if(action==='attendance'&&method==='GET'){const {data,error}=await rpc('crew_attendance_roster',{p_event_id:payload.eventId});if(error)throw Error(error.message||'Attendance roster failed.');return data;}
 const {data,error}=await rpc('crew_api',{p_action:action,p_method:method,p_payload:payload});
 if(error)throw Error(error.message||error.details||'Crew service request failed.');
 return data;
}
async function featureApi(action,feature,payload){const {data,error}=await rpc('crew_features',{p_action:action,p_feature:feature,p_payload:payload||{}});if(error){const m=error.message||'Feature request failed.';if(/could not find the function|schema cache/i.test(m))throw Error('Crew features are not enabled in the database yet. Apply supabase/migrations/202611090005_feature_suite.sql in Supabase SQL Editor, then reload the app.');throw Error(m);}return data;}
function notice(text){let t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(notice.timer);notice.timer=setTimeout(()=>t.classList.remove('show'),3000);}
function cacheKey(userId){return 'kc-bootstrap-v2:'+userId;}
function paintUser(){if(!S.user)return;$('#profileName').textContent=S.user.name||S.user.email;$('#profileRole').textContent=role(S.user.role);$('#avatar').innerHTML=avatarMarkup(S.user);$('#topAvatar').innerHTML=avatarMarkup(S.user,'small');}
async function refresh(){
 const d=await api('bootstrap');
 S.user=d.user;S.events=d.events||[];S.announcements=d.announcements||[];S.members=d.members||[];
 S.offline=false;S.error='';
 try{const sessionResult=await auth.getSession();const cacheUserId=sessionResult?.data?.session?.user?.id||S.user.auth_id||S.user.id;if(cacheUserId)localStorage.setItem(cacheKey(cacheUserId),JSON.stringify({savedAt:Date.now(),user:S.user,events:S.events,announcements:S.announcements}));}catch{}
 paintUser();paint();
}
function restoreOffline(user){
 const id=user?.id||user?.auth_id;if(!id)return false;
 try{
  const cached=JSON.parse(localStorage.getItem(cacheKey(id))||'null');
  if(!cached?.user)return false;
  S.user=cached.user;S.events=cached.events||[];S.announcements=cached.announcements||[];S.members=[];
  S.offline=true;S.error='Offline mode: showing your last saved crew data. Changes and live updates need an internet connection.';
  paintUser();paint();return true;
 }catch{return false;}
}
function button(label,view){return '<button class="primary" data-view="'+view+'">'+label+'</button>';}
function welcome(title,sub,action=''){return '<div class="welcome"><div><div class="eyebrow"><span class="eyedot"></span>'+role(S.user.role).toUpperCase()+' SPACE <span class="muted">/</span> KINETIC CREW</div><h1>'+title+'</h1><p>'+sub+'</p></div>'+action+'</div>';}
function section(title,sub,act=''){return '<div class="sectionhead"><div><h2>'+title+'</h2><p>'+sub+'</p></div>'+act+'</div>';}
function empty(title,sub){return '<div class="empty"><div class="emptyicon">✳</div><b>'+title+'</b><p>'+sub+'</p></div>';}
function stat(title,value,foot,ico){return '<div class="stat"><div class="statlabel"><span>'+title+'</span><span>'+ico+'</span></div><b class="statvalue">'+value+'</b><small>'+foot+'</small></div>';}

function avatarMarkup(user,size='') {const src=user?.avatar_url;return src?'<img class="avatar-photo '+size+'" src="'+esc(src)+'" alt="'+esc(user.name||'Crew member')+'">':'<span class="avatar-fallback '+size+'">'+esc(initials(user?.name||user?.email))+'</span>';}
function profilePage(){const u=S.user||{},photo=u.avatar_url||'';return welcome('My profile','Your crew identity, personal details and account settings.')+'<div class="profile-layout"><section class="surface profile-card"><div class="profile-cover"></div><div class="profile-avatar-wrap"><img id="profilePhotoPreview" class="profile-photo" src="'+esc(photo||'/kinetic-crew-logo.svg')+'" alt="Profile photo"><label class="photo-edit" for="profilePhotoInput">Change photo</label><input id="profilePhotoInput" type="file" accept="image/png,image/jpeg,image/webp" hidden></div><h2>'+esc(u.name||'Crew member')+'</h2><p>'+esc(role(u.role))+' · '+esc(u.email||'')+'</p><span class="pill">KINETIC CREW MEMBER</span></section><form id="profileForm" class="surface profile-edit">'+formTitle('✎','Edit your profile','Your name and bio are visible to your crew.')+'<label class="field">Full name<input name="name" maxlength="100" required value="'+esc(u.name||'')+'"></label><label class="field">About you<textarea name="bio" maxlength="500" rows="4" placeholder="Dance styles, interests, role in the crew…">'+esc(u.bio||'')+'</textarea></label><label class="field">Email address<input value="'+esc(u.email||'')+'" disabled></label><label class="field">Username<input value="'+esc(u.username||'Not set')+'" disabled></label><p class="hint">Profile photo: JPG, PNG or WebP · Maximum 5 MB.</p><button class="primary full">Save profile</button><button type="button" class="outline full" id="logoutProfile">Sign out ↗</button></form></div>';}
function readKey(){return 'kc-read-notices:'+String(S.user?.id||S.user?.auth_id||'guest');}
function prefsKey(){return 'kc-notification-prefs:'+String(S.user?.auth_id||S.user?.id||'guest');}
function notificationPrefs(){try{return {sound:true,push:localStorage.getItem('kc-push-enabled')==='yes',...JSON.parse(localStorage.getItem(prefsKey())||'{}')}}catch{return {sound:true,push:false}}}
function saveNotificationPrefs(patch){const next={...notificationPrefs(),...patch};localStorage.setItem(prefsKey(),JSON.stringify(next));return next;}
function isRead(id){try{return JSON.parse(localStorage.getItem(readKey())||'[]').includes(id)}catch{return false}}
function markRead(id){const ids=new Set(JSON.parse(localStorage.getItem(readKey())||'[]'));ids.add(id);localStorage.setItem(readKey(),JSON.stringify([...ids]));}
function unread(){return S.announcements.filter(a=>!isRead(a.id)).length}
function playNoticeSound(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),now=ctx.currentTime;[660,880].forEach((hz,i)=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=hz;gain.gain.setValueAtTime(.0001,now+i*.12);gain.gain.exponentialRampToValueAtTime(.11,now+i*.12+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+i*.12+.22);osc.connect(gain);gain.connect(ctx.destination);osc.start(now+i*.12);osc.stop(now+i*.12+.24);});setTimeout(()=>ctx.close(),700);}catch{}}
function notificationCard(a){const read=isRead(a.id);return '<article class="notification-item '+(read?'read':'unread')+'" data-notice-id="'+esc(a.id)+'"><span class="notification-icon">'+(read?'✓':'✦')+'</span><div class="notification-copy"><div class="announce-meta"><b>CREW UPDATE</b><span>·</span><span>'+esc(dt(a.created_at))+'</span><span class="notice-state">'+(read?'READ':'NEW')+'</span></div><h3>'+esc(a.title)+'</h3><p>'+esc(a.body)+'</p><small>From '+esc(a.author_name||'Kinetic Crew Admin')+'</small></div><button class="notice-read-button" data-read-notice="'+esc(a.id)+'" aria-label="'+(read?'Already read':'Mark as read')+'" '+(read?'disabled':'')+'>'+(read?'✓':'Mark read')+'</button></article>';}
function notificationsPage(){
 const prefs=notificationPrefs(),filter=S.noticeFilter||'all',query=(S.noticeQuery||'').trim().toLowerCase();
 const filtered=S.announcements.filter(a=>(filter==='all'||(filter==='unread'&&!isRead(a.id)))&&(!query||(String(a.title||'')+' '+String(a.body||'')+' '+String(a.author_name||'')).toLowerCase().includes(query)));
 return welcome('Your notifications','All the important moments from your crew, in one place.')+
 '<section class="notice-hero"><div class="notice-hero-copy"><span class="notice-kicker">KINETIC CREW / INBOX</span><h2>'+unread()+' <em>new</em> updates</h2><p>Stay close to rehearsals, events and everything happening in the crew.</p></div><div class="notice-orbit"><span>✳</span><i></i><b></b></div></section>'+
 '<section class="notice-controls"><div class="notice-tabs"><button data-notice-filter="all" class="'+(filter==='all'?'active':'')+'">All <span>'+S.announcements.length+'</span></button><button data-notice-filter="unread" class="'+(filter==='unread'?'active':'')+'">Unread <span>'+unread()+'</span></button></div><div class="notice-actions"><input id="noticeSearch" type="search" placeholder="Search notifications…" value="'+esc(S.noticeQuery||'')+'"><button class="outline" id="markAllRead" '+(unread()?'':'disabled')+'>Mark all read</button></div></section>'+
 '<section class="notice-layout"><div class="notice-feed"><div class="notice-feed-head"><div><b>Activity</b><small>'+filtered.length+' updates</small></div><span class="notice-live"><i></i> CREW FEED</span></div>'+
 (filtered.length?filtered.map(notificationCard).join(''):empty(query?'No matching updates':'You are all caught up',query?'Try a different search.':'New crew announcements will appear here.'))+'</div>'+
 '<aside class="notice-settings"><div class="notice-settings-head"><span>✦</span><div><b>Notification settings</b><small>Make alerts work your way</small></div></div>'+
 '<label class="notice-pref"><span><b>In-app sound</b><small>Play a soft chime for alerts</small></span><input type="checkbox" id="noticeSound" '+(prefs.sound?'checked':'')+'><i></i></label>'+
 '<div class="notice-pref notice-push-pref"><span><b>Device notifications</b><small>Get crew alerts outside the app</small></span><button class="outline" id="enablePush">'+(prefs.push?'Manage':'Enable')+'</button></div>'+
 '<button class="notice-test-sound" id="testNoticeSound">♫ &nbsp; Test notification sound</button>'+
 '<p class="notice-settings-foot">Device permissions are controlled by your browser or Android settings.</p></aside></section>';
}
function loadOptionalScript(src){return new Promise((resolve,reject)=>{const existing=[...document.scripts].find(s=>s.src===src);if(existing){if(existing.dataset.loaded==="yes")return resolve();existing.addEventListener("load",resolve,{once:true});existing.addEventListener("error",reject,{once:true});return;}const script=document.createElement("script");script.src=src;script.async=true;script.onload=()=>{script.dataset.loaded="yes";resolve();};script.onerror=reject;document.head.appendChild(script);});} 
async function startQr(){if(!("BarcodeDetector" in window)&&!window.jsQR){try{await loadOptionalScript("https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js");}catch{notice("QR scanner could not load. Check your connection and try again.");return;}}if(!navigator.mediaDevices?.getUserMedia){notice('Camera access is unavailable in this browser. Use manual member selection.');return;}try{S.qrStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const video=$('#qrVideo');video.srcObject=S.qrStream;$('#qrScanner').hidden=false;await video.play();const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});const detector='BarcodeDetector'in window?new BarcodeDetector({formats:['qr_code']}):null;const scan=async()=>{if(!S.qrStream)return;try{let raw='';if(video.readyState>=2){if(detector){const codes=await detector.detect(video);raw=codes[0]?.rawValue||'';}else if(window.jsQR){canvas.width=video.videoWidth;canvas.height=video.videoHeight;ctx.drawImage(video,0,0,canvas.width,canvas.height);raw=window.jsQR(ctx.getImageData(0,0,canvas.width,canvas.height).data,canvas.width,canvas.height)?.data||'';}else{stopQr();notice('QR scanner library unavailable. Refresh and try again.');return;}}if(raw){const parts=raw.split(':');if(parts.length===3&&parts[0]==='KC_EVENT_ATTENDANCE'&&/^[0-9a-f-]{36}$/i.test(parts[1])&&/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(parts[2])){const eventId=parts[1],memberEmail=parts[2];stopQr();$('#qrScanner').hidden=true;await action(async()=>{const result=await api('qr-attendance','POST',{eventId,memberEmail});S.rosterEvent=eventId;S.roster=await api('attendance?eventId='+encodeURIComponent(eventId));notice(result.message);});return;}notice('Invalid event QR. Ask the member to open the QR from that event card.');}}catch(err){console.warn('QR scan frame failed',err);}if(S.qrStream)requestAnimationFrame(scan)};requestAnimationFrame(scan)}catch(err){stopQr();notice(err?.name==='NotAllowedError'?'Allow camera access to scan member QR codes.':'Camera unavailable. Use manual member selection.');}}
function stopQr(){if(S.qrStream){S.qrStream.getTracks().forEach(t=>t.stop());S.qrStream=null;}}

function card(e){let act=e.attended?'<span class="pill">✓ Attended</span>':e.registered?'<span class="pill">✓ Registered</span>':'<span class="event-open-hint">View details ↗</span>';return '<article class="event event-clickable" role="button" tabindex="0" data-open-event="'+esc(e.id)+'"><div class="cover"><span class="datechip">'+esc(ds(e.starts_at))+'</span><span class="coversymbol">✳</span><span class="covercode">KC / EVENT '+esc(String(e.id).slice(0,5).toUpperCase())+'</span></div><div class="eventbody"><div class="eventtype"><i></i>'+(new Date(e.starts_at)>new Date()?'UPCOMING EVENT':'CREW EVENT')+'</div><h3>'+esc(e.title)+'</h3><p class="eventdesc">'+esc(e.description||'A moment to connect, create, and move together.')+'</p><div class="eventmeta"><span>◷ &nbsp;'+esc(dt(e.starts_at))+'</span><span>⌖ &nbsp;'+esc(e.location||'Location TBA')+'</span></div><div class="eventbottom"><span class="capacity">'+Number(e.registration_count||0)+' / '+Number(e.capacity||0)+' registered</span>'+act+'</div></div></article>';}
function eventDetailPage(){const e=S.events.find(x=>String(x.id)===String(S.selectedEvent));if(!e)return eventsPage();const act=e.attended?'<span class="pill">✓ Attendance marked</span>':e.registered?'<div class="event-pass-actions"><button class="outline" data-otp="'+esc(e.id)+'">Get event OTP</button><button class="primary" data-event-qr="'+esc(e.id)+'">Show event QR</button></div>':'<button class="primary" data-register="'+esc(e.id)+'">Register for this event →</button>';return '<button class="backlink" data-view="events">← Back to all events</button><div class="event-detail"><div class="event-detail-hero"><div class="eventtype"><i></i>'+ (new Date(e.starts_at)>new Date()?'UPCOMING EVENT':'CREW EVENT')+'</div><img class="detail-brand-logo" src=".//kinetic-crew-logo.svg" alt="Kinetic Crew logo" loading="eager"><h1>'+esc(e.title)+'</h1><p>'+esc(e.description||'Join the crew for this event.')+'</p></div><div class="event-detail-grid"><section class="surface detail-main"><h2>Event details</h2><div class="detail-facts"><div><small>DATE & TIME</small><b>'+esc(dt(e.starts_at))+'</b></div><div><small>LOCATION</small><b>'+esc(e.location||'To be announced')+'</b></div><div><small>REGISTRATIONS</small><b>'+Number(e.registration_count||0)+' / '+Number(e.capacity||0)+'</b></div><div><small>YOUR STATUS</small><b>'+(e.attended?'Attended':e.registered?'Registered':'Not registered')+'</b></div></div><h3>About this event</h3><p class="detail-description">'+esc(e.description||'More event information will be shared by the crew admins.')+'</p></section><aside class="surface detail-action"><h2>Join this event</h2><p>'+(e.registered?'You are on the guest list. Your event check-in pass is available below.':'Register to reserve your place. After registering, your event-specific OTP and QR pass will appear here.')+'</p>'+act+'</aside></div>'+(admin()?'<div class="detail-admin"><button class="outline danger-link" data-delete-event="'+esc(e.id)+'">Delete event</button></div>':'')+'</div>';}
function announcement(a){return '<article class="announcement"><div class="announceicon">♧</div><div class="announcebody"><div class="announce-meta"><b>CREW SIGNAL</b><span>·</span><span>'+esc(dt(a.created_at))+'</span></div><h3>'+esc(a.title)+'</h3><p>'+esc(a.body)+'</p><div class="author">Posted by <b>'+esc(a.author_name||'Crew Admin')+'</b></div></div></article>';}
function formTitle(icon,title,sub){return '<div class="formtitle"><div class="formicon">'+icon+'</div><div><h3>'+title+'</h3><p>'+sub+'</p></div></div>';}
function eventForm(){return '<form id="eventForm" class="surface formgrid">'+formTitle('＋','Create an event','Put the next crew moment on the calendar.')+'<label class="field">Event name<input name="title" maxlength="120" required placeholder="Freshers Showcase"></label><label class="field">Location<input name="location" maxlength="160" placeholder="Dance studio / auditorium"></label><label class="field">Date & time<input name="starts_at" type="datetime-local" required></label><label class="field">Capacity<input name="capacity" type="number" min="1" max="10000" value="40" required></label><label class="field span2">Description<textarea name="description" rows="3" maxlength="2500" placeholder="What should members know?"></textarea></label><button class="primary">＋ Publish event</button></form>';}
function updateForm(){return '<form id="updateForm" class="surface publish">'+formTitle('♧','Broadcast a message','Send the crew a clear signal.')+'<label class="field">Headline<input name="title" maxlength="140" required placeholder="What is the update?"></label><label class="field">Message<textarea name="body" rows="5" maxlength="5000" required placeholder="Share the details…"></textarea></label><label class="field">Audience<select name="audience"><option value="all">Everyone</option><option value="member">Members</option><option value="admin">Admins</option><option value="super_admin">Super admins</option></select></label><button class="primary full">Publish update →</button><div class="notice">Announcements appear in Crew HQ. Push notifications when the app is closed require a separate delivery setup.</div></form>';}
function home(){const next=S.events.find(e=>new Date(e.starts_at)>=new Date());return welcome('Welcome back, '+esc((S.user.name||S.user.email).split('@')[0].split(' ')[0])+'.','Your crew, your events, all in one place.')+'<div class="home-hero"><div class="home-hero-copy"><span class="eyebrow"><i class="eyedot"></i> KINETIC CREW</span><h2>Move together.<br><em>Make it count.</em></h2><p>Everything happening with your crew, in one simple space.</p><button class="primary" data-view="events">Explore events →</button></div><img class="hero-brand-logo" src=".//kinetic-crew-logo.svg" alt="Kinetic Crew logo" loading="eager"></div><div class="home-shortcuts"><button data-view="events"><span>▦</span><b>Events</b><small>Discover and register</small></button><button data-view="notifications"><span>♧</span><b>Updates</b><small>Latest crew news</small></button><button data-view="profile"><span>◉</span><b>My profile</b><small>Your account details</small></button>'+(admin()?'<button data-view="attendance"><span>◎</span><b>Attendance</b><small>Manage check-ins</small></button>':'')+'</div>'+section('Next event','Your next crew moment.','<button class="textlink" data-view="events">View all →</button>')+(next?'<div class="eventgrid single-event">'+card(next)+'</div>':empty('No upcoming events','New crew events will appear here.'))+section('Latest update','A quick look at what is new.','<button class="textlink" data-view="notifications">All updates →</button>')+(S.announcements[0]?'<div class="announcements">'+announcement(S.announcements[0])+'</div>':empty('No new updates','Crew announcements will appear here.'));}
function eventsPage(){return welcome('Events & registrations','The next moment is waiting. Find your event and lock in.',admin()?button('＋ New event','new-event'):'')+(admin()?eventForm():'')+section('Upcoming moments','Register once. Show up ready.','<span class="pill">'+S.events.length+' EVENTS</span>')+'<div class="eventgrid">'+(S.events.map(card).join('')||empty('No events yet','A crew admin can publish the first event here.'))+'</div>';}
function updatesPage(){return welcome('Crew updates','Announcements, changes, and the latest from your people.',admin()?button('＋ New update','new-update'):'')+'<div class="twoCol"><div class="announcements">'+(S.announcements.map(announcement).join('')||empty('It is quiet in here','Updates will appear here when published.'))+'</div>'+(admin()?updateForm():'')+'</div>';}
function rosterRows(rows){return rows&&rows.length?rows.map(m=>'<div class="rosterrow"><div class="avatar">'+esc(initials(m.name))+'</div><div class="rosterperson"><b>'+esc(m.name)+'</b><small>'+esc(m.email)+'</small></div><span class="status '+(m.status==='present'||m.attended?'present':m.status==='absent'?'absent':'pending')+'">'+(m.status==='present'||m.attended?'Present':m.status==='absent'?'Absent':'Pending')+'</span></div>').join(''):empty('No registrations yet','Members who register will appear here.');}
function attendancePage(){if(!admin())return empty('Admin access required','Attendance verification is available to admins and super admins.');const finalized=!!S.roster?.finalized;return welcome('Attendance desk','Scan an event QR pass or verify a member with their event OTP.')+'<div class="attendancegrid"><form id="verifyForm" class="surface verifyform">'+formTitle('▦','Attendance verification','Choose the event, then scan the member QR or enter their six-digit OTP.')+'<label class="field">Event<select name="eventId" required><option value="">Select an event…</option>'+S.events.map(e=>'<option value="'+esc(e.id)+'" '+(String(S.rosterEvent)===String(e.id)?'selected':'')+'>'+esc(e.title)+'</option>').join('')+'</select></label><label class="field">Member email (for OTP verification)<input name="memberEmail" type="email" placeholder="member@example.com" required></label><label class="field">Six-digit event OTP<input name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}" placeholder="Enter OTP" required></label><button type="submit" class="primary full" '+(finalized?'disabled':'')+'>Verify OTP & mark present</button><div class="or-divider"><span>OR</span></div><button type="button" class="outline full" id="openQrScanner" '+(finalized?'disabled':'')+'>▦ Scan event QR — instant check-in</button><div id="qrScanner" class="qr-scanner" hidden><video id="qrVideo" autoplay playsinline></video><button type="button" class="outline full" id="closeQrScanner">Close scanner</button></div><p class="hint">QR and OTP are alternative check-in methods. Both verify event registration on the server.</p></form><div class="surface"><div class="rosterhead"><div><h3>Event roster</h3><p>Present, absent and pending registrations.</p></div><select id="rosterSelect" class="select"><option value="">Choose event</option>'+S.events.map(e=>'<option value="'+esc(e.id)+'" '+(String(S.rosterEvent)===String(e.id)?'selected':'')+'>'+esc(e.title)+'</option>').join('')+'</select></div><div id="rosterBody">'+(S.roster?rosterRows(S.roster.roster):empty('Roster is waiting','Select an event to see registrations.'))+'</div>'+(S.roster?'<div class="attendance-actions"><button class="outline" id="exportAttendance">Export Excel CSV</button><button class="primary" id="finalizeAttendance" '+(finalized?'disabled':'')+'>'+(finalized?'Attendance finalized':'Finalize & mark remaining absent')+'</button></div>'+(finalized?'<p class="hint">This event has been finalized. Remaining registered members are recorded as absent.</p>':'<p class="hint">Finalize only after check-in closes. This marks every remaining registered member absent.</p>'):'')+'</div></div>';}function peoplePage(){if(!admin())return empty('Admin access required','Crew directory is available to admins and super admins.');return welcome('Crew directory','The people behind every performance.')+'<div class="peopleStats"><div class="peopleStat">♙<span>CREW ACCOUNTS</span><b>'+S.members.length+'</b></div><div class="peopleStat">✦<span>ADMINS</span><b>'+S.members.filter(m=>m.role!=='member').length+'</b></div><div class="peopleStat">✳<span>MEMBERS</span><b>'+S.members.filter(m=>m.role==='member').length+'</b></div></div><div class="surface directory"><div class="directoryhead"><div><h3>Crew directory</h3><p>Review roles and see who is in the movement.</p></div><span class="pill">'+S.members.length+' ACCOUNTS</span></div><div class="tablewrap"><table><thead><tr><th>CREW MEMBER</th><th>ROLE</th><th>EVENTS</th><th>JOINED</th>'+(superadmin()?'<th>ACCESS</th>':'')+'</tr></thead><tbody>'+S.members.map(m=>'<tr data-profile-row="'+esc(m.auth_id)+'"><td><div class="person">'+avatarMarkup(m)+'<div><b>'+esc(m.name)+'</b><small>'+esc(m.email)+'</small></div></div><details class="member-edit"><summary>Edit profile</summary><label class="field">Name<input name="member_name" maxlength="100" value="'+esc(m.name)+'"></label><label class="field">Bio<textarea name="member_bio" maxlength="500" rows="2">'+esc(m.bio||'')+'</textarea></label><button type="button" class="outline profile-admin-save">Save member</button></details></td><td><span class="roletag '+esc(m.role)+'">'+esc(role(m.role))+'</span></td><td>'+Number(m.event_count||0)+'</td><td>'+esc(new Date(m.created_at).toLocaleDateString())+'</td>'+(superadmin()?'<td>'+(m.auth_id===S.user.auth_id?'You':'<select class="select role-select" data-id="'+esc(m.auth_id)+'"><option value="member" '+(m.role==='member'?'selected':'')+'>Member</option><option value="admin" '+(m.role==='admin'?'selected':'')+'>Admin</option></select>')+'</td>':'')+'</tr>').join('')+'</tbody></table></div></div>';}

const featureLabels={rehearsals:'Rehearsals',leave:'Leave requests',expenses:'Expenses',memories:'KC Memories',auditions:'Audition portal',polls:'Polls & voting',chat:'Crew chat',achievements:'Achievements'};
const featureMeta={
 rehearsals:['Plan a practice session','Create rehearsals, assign a choreographer and share the venue.','Session title','Practice details','Create session'],
 leave:['Request time away','Send a leave request to the crew admins.','Leave request','Reason and dates','Submit request'],
 expenses:['Crew expenses','Record event costs and keep the team budget transparent.','Expense item','Amount, category and notes','Add expense'],
 memories:['KC Memories','Share the photo album and video links from crew moments.','Memory title','Caption and media link','Share memory'],
 auditions:['Audition portal','Publish auditions or submit your audition details and video link.','Audition / application','Dance style, contact and audition video link','Submit'],
 polls:['Crew polls','Vote on songs, themes and crew decisions.','Poll question','Add options separated by commas','Publish poll'],
 chat:['Crew chat','A shared space for quick crew conversations.','Message title','Write your message','Send message'],
 achievements:['Achievements','Recognize crew milestones and standout contributions.','Achievement title','Describe the achievement and recipient','Award achievement']
};
const featureKeys=Object.keys(featureLabels);
function featureForm(key){
 const meta=featureMeta[key],isPoll=key==='polls',isLeave=key==='leave',isExpense=key==='expenses',isAudition=key==='auditions',isMemory=key==='memories',isChat=key==='chat',isRehearsal=key==='rehearsals',isAchievement=key==='achievements';
 return '<form class="surface feature-form" data-feature-form="'+key+'">'+formTitle('✦',meta[0],meta[1])+'<label class="field">'+meta[2]+'<input name="title" maxlength="160" required placeholder="'+(isChat?'Quick crew update':meta[2])+'"></label><label class="field">'+meta[3]+'<textarea name="body" rows="3" maxlength="5000" '+(isChat?'required':'')+' placeholder="'+(isPoll?'e.g. Song A, Song B, Song C':isExpense?'e.g. ₹1200 · costumes · event name':isMemory?'Add a caption and paste a shareable media URL':isAudition?'Dance style, applicant details and video URL':isLeave?'Dates and reason':'Add useful details…')+'"></textarea></label>'+
 (isPoll?'<p class="hint">Separate each option with a comma. Members can change their vote until the poll closes.</p>':'')+
 (isExpense?'<label class="field">Amount (₹)<input name="amount" type="number" min="0" step="0.01" required></label><label class="field">Category<input name="category" maxlength="80" placeholder="Travel / costumes / venue"></label>':'')+
 (isLeave?'<label class="field">From<input name="from_date" type="date" required></label><label class="field">To<input name="to_date" type="date" required></label>':'')+
 (isRehearsal?'<label class="field">Date & time<input name="session_at" type="datetime-local" required></label><label class="field">Location<input name="location" maxlength="160" placeholder="Practice room / studio"></label>':'')+
 (isAchievement?'<label class="field">Awarded to<input name="recipient" maxlength="120" required placeholder="Crew member name"></label>':'')+
 (isAudition?'<label class="field">Dance style<input name="style" maxlength="80" placeholder="Hip-hop / freestyle / classical"></label><label class="field">Audition video URL<input name="media_url" type="url" placeholder="https://…"></label>':'')+
 (isMemory?'<label class="field">Photo / video URL<input name="media_url" type="url" placeholder="Paste a shareable link"></label>':'')+
 '<button class="primary full">'+meta[4]+' →</button></form>';
}
function featureCard(key,item){
 const data=item.data||{},status=item.status||'open';
 let extra='';
 if(key==='polls'){
   const opts=String(item.body||'').split(',').map(x=>x.trim()).filter(Boolean);
   extra='<div class="poll-options">'+opts.map(o=>'<button class="outline poll-vote" data-vote-id="'+esc(item.id)+'" data-choice="'+esc(o)+'">'+esc(o)+'</button>').join('')+'</div><button class="textlink" data-poll-results="'+esc(item.id)+'">View results</button>';
 }
 if(key==='leave'||key==='auditions'){
   extra='<div class="feature-status">Status: <b>'+esc(status.toUpperCase())+'</b></div>';
   if(admin()&&status==='pending')extra+='<div class="feature-actions"><button class="outline" data-moderate="'+esc(item.id)+'" data-status="approved" data-feature="'+key+'">Approve</button><button class="outline" data-moderate="'+esc(item.id)+'" data-status="rejected" data-feature="'+key+'">Reject</button></div>';
   if(admin()&&key==='auditions'&&status==='open')extra+='<div class="feature-actions"><button class="outline" data-moderate="'+esc(item.id)+'" data-status="selected" data-feature="'+key+'">Select</button><button class="outline" data-moderate="'+esc(item.id)+'" data-status="rejected" data-feature="'+key+'">Not selected</button></div>';
 }
 if(key==='expenses')extra='<div class="feature-status">₹'+esc(data.amount||'0')+' · '+esc(data.category||'General')+'</div>';
 if(data.media_url)extra+='<p><a class="feature-link" href="'+esc(data.media_url)+'" target="_blank" rel="noopener">Open shared media ↗</a></p>';
 if(data.from_date)extra+='<p class="feature-meta">'+esc(data.from_date)+' → '+esc(data.to_date||data.from_date)+'</p>';
 if(key==='rehearsals'&&data.session_at)extra+='<p class="feature-meta">◷ '+esc(dt(data.session_at))+' · '+esc(data.location||'Location TBA')+'</p>';
 if(key==='achievements'&&data.recipient)extra+='<p class="feature-meta">Awarded to '+esc(data.recipient)+'</p>';
 return '<article class="surface feature-card"><div class="feature-card-top"><span class="pill">'+esc(status)+'</span><small>'+esc(dt(item.created_at))+'</small></div><h3>'+esc(item.title)+'</h3><p>'+esc(item.body||'')+'</p>'+extra+'<div class="feature-card-foot"><span>By '+esc(item.author_name||'Crew member')+'</span>'+(admin()||item.author_id===S.user.auth_id?'<button class="textlink" data-feature-delete="'+esc(item.id)+'" data-feature="'+key+'">Delete</button>':'')+'</div></article>';
}
function featurePage(key){
 const meta=featureMeta[key],items=S.featureItems[key]||[];
 const canCreate=key!=='expenses'&&key!=='auditions'&&key!=='achievements'||admin();
 const list=items.map(x=>featureCard(key,x)).join('');
 return welcome(featureLabels[key],meta[1],key==='achievements'&&admin()?button('＋ Award achievement','achievement-form'):'')+
 (key==='achievements'&&admin()?'<div id="achievementFormHost">'+featureForm(key)+'</div>':'')+
 (canCreate&&key!=='achievements'?featureForm(key):'')+
 section(key==='chat'?'Crew conversation':key==='memories'?'Shared memories':featureLabels[key],key==='polls'?'Choose an option and cast your vote.':'The latest activity from your crew.', '<span class="pill">'+items.length+' ITEMS</span>')+
 '<div class="feature-grid">'+(list||empty('Nothing here yet','Be the first to add something to this space.'))+'</div>';
}
function calendarPage(){
 const rows=S.events.slice().sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));
 const groups={};
 rows.forEach(e=>{const d=new Date(e.starts_at);const k=Number.isNaN(+d)?'Date TBA':d.toLocaleDateString([],{month:'long',year:'numeric'});(groups[k]||(groups[k]=[])).push(e);});
 return welcome('Crew calendar','A clear schedule of performances, events and crew moments.')+
 '<div class="calendar-list">'+(Object.keys(groups).map(k=>'<section class="calendar-month"><h2>'+esc(k)+'</h2><div class="eventgrid">'+groups[k].map(card).join('')+'</div></section>').join('')||empty('No events scheduled','Published events will appear on the calendar.'))+'</div>';
}
function leaderboardPage(){
 const sorted=S.leaderboard||S.members.slice().sort((a,b)=>Number(b.event_count||0)-Number(a.event_count||0));
 return welcome('Crew leaderboard','Recognizing participation across the crew.')+
 '<div class="surface leaderboard-list">'+(sorted.length?sorted.map((m,i)=>'<div class="leader-row"><b class="leader-rank">#'+(i+1)+'</b><div class="avatar">'+esc(initials(m.name))+'</div><div class="leader-person"><b>'+esc(m.name)+'</b><small>'+esc(role(m.role))+'</small></div><strong>'+Number(m.event_count||0)+' <small>events</small></strong></div>').join(''):empty('Leaderboard is warming up','Member participation will appear as the crew grows.'))+'</div><p class="hint">Current ranking is based on event registrations, not verified attendance. A future scoring upgrade can include attendance and volunteering.</p>';
}

function paint(){const nav=admin()?[['overview','⌂','Overview','GENERAL'],['events','▦','Events','PROGRAMS'],['calendar','▦','Calendar','PROGRAMS'],['rehearsals','◷','Rehearsals','PROGRAMS'],['polls','◉','Polls & voting','COMMUNITY'],['memories','▧','KC Memories','COMMUNITY'],['chat','✉','Crew chat','COMMUNITY'],['leave','↗','Leave requests','PEOPLE'],['auditions','☆','Auditions','PEOPLE'],['leaderboard','♜','Leaderboard','PEOPLE'],['achievements','✦','Achievements','PEOPLE'],['expenses','₹','Expenses','MANAGEMENT'],['attendance','◎','Attendance desk','MANAGEMENT'],['people','♙','Crew directory','MANAGEMENT'],['notifications','♧','Notifications','GENERAL'],['profile','◉','My profile','ACCOUNT']]:[['overview','⌂','Home','GENERAL'],['events','▦','Events','PROGRAMS'],['calendar','▦','Calendar','PROGRAMS'],['rehearsals','◷','Rehearsals','PROGRAMS'],['polls','◉','Polls & voting','COMMUNITY'],['memories','▧','KC Memories','COMMUNITY'],['chat','✉','Crew chat','COMMUNITY'],['leave','↗','Leave requests','ACCOUNT'],['auditions','☆','Auditions','ACCOUNT'],['achievements','✦','Achievements','ACCOUNT'],['notifications','♧','Notifications','GENERAL'],['profile','◉','My profile','ACCOUNT']];let group='';$('#nav').innerHTML=nav.map(n=>(group!==n[3]?(group=n[3],'<div class="navtitle navgroup-title">'+group+'</div>'):'')+'<button class="navitem '+(S.view===n[0]?'active':'')+'" data-view="'+n[0]+'"><span class="nicon">'+n[1]+'</span><span>'+n[2]+'</span>'+(n[0]==='notifications'&&unread()?'<span class="count">'+unread()+'</span>':'')+'</button>').join('');$('#crumb').textContent=({overview:'Overview',events:'Events & registrations',calendar:'Crew calendar',rehearsals:'Rehearsals',leave:'Leave requests',expenses:'Expenses',memories:'KC Memories',auditions:'Audition portal',polls:'Polls & voting',chat:'Crew chat',achievements:'Achievements',leaderboard:'Leaderboard',updates:'Crew updates',notifications:'Notifications',profile:'My profile',attendance:'Attendance desk',people:'Crew directory','event-detail':'Event details'}[S.view]||'Overview');let fn={overview:home,events:eventsPage,calendar:calendarPage,rehearsals:()=>featurePage('rehearsals'),leave:()=>featurePage('leave'),expenses:()=>featurePage('expenses'),memories:()=>featurePage('memories'),auditions:()=>featurePage('auditions'),polls:()=>featurePage('polls'),chat:()=>featurePage('chat'),achievements:()=>featurePage('achievements'),leaderboard:leaderboardPage,updates:updatesPage,notifications:notificationsPage,profile:profilePage,attendance:attendancePage,people:peoplePage,'event-detail':eventDetailPage}[S.view]||home;$('#app').innerHTML=(S.error?'<div class="alert"><span>'+esc(S.error)+'</span><button data-clear>×</button></div>':'' )+(S.offline?'<div class="offline-strip">OFFLINE · LAST SAVED DATA</div>':'')+fn();}
async function go(v){S.view=v;S.error='';$('#sidebar').classList.remove('open');$('#navShade').classList.remove('open');if(featureKeys.includes(v)){try{S.featureItems[v]=await featureApi('list',v,{});}catch(e){S.error=e.message||'Could not load this feature.';}}if(v==='leaderboard'){try{S.leaderboard=await featureApi('leaderboard',null,{});}catch(e){S.error=e.message||'Could not load leaderboard.';}}paint();window.scrollTo({top:0,behavior:'smooth'});}
async function exportAttendance(){if(!S.roster?.roster?.length){notice('No attendance rows to export.');return;}const rows=[['Member name','Email','Attendance status','Registered at'],...S.roster.roster.map(m=>[m.name,m.email,m.status||(m.attended?'present':'pending'),m.registered_at||''])];if(window.XLSX){const wb=XLSX.utils.book_new();const ws=XLSX.utils.aoa_to_sheet(rows);XLSX.utils.book_append_sheet(wb,ws,'Attendance');XLSX.writeFile(wb,'kinetic-crew-attendance-'+S.rosterEvent+'.xlsx');notice('Excel attendance workbook downloaded.');return;}const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='kinetic-crew-attendance-'+S.rosterEvent+'.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);notice('Attendance CSV downloaded. Open it in Excel.');}
async function action(fn){try{S.error='';await fn();}catch(e){S.error=e.message||'Something went wrong.';}paint();}
function showEventQr(eventId,title){const payload='KC_EVENT_ATTENDANCE:'+eventId+':'+S.user.email;$('#modalRoot').innerHTML='<div class="modalback" id="eventQrBackdrop"><div class="modal" role="dialog" aria-modal="true"><button class="iconbutton modalclose" id="closeEventQr">×</button><div class="modalemblem">▦</div><div class="eyebrow" style="justify-content:center">EVENT ATTENDANCE PASS</div><h2>'+esc(title)+'</h2><p>This QR is unique to this event and your registered account. Show it to an admin or super admin scanner.</p><div id="eventQrImage" class="member-qr"></div><p class="modalhint">No OTP needed when scanned</p><button class="primary full" id="doneEventQr">Done ✓</button></div></div>';if(window.QRCode)new QRCode($('#eventQrImage'),{text:payload,width:220,height:220,colorDark:'#282641',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});$('#closeEventQr').onclick=$('#doneEventQr').onclick=()=>$('#modalRoot').innerHTML='';$('#eventQrBackdrop').onclick=e=>{if(e.target.id==='eventQrBackdrop')$('#modalRoot').innerHTML='';};}
function showOtp(code,expires,title){$('#modalRoot').innerHTML='<div class="modalback" id="otpBackdrop"><div class="modal" role="dialog" aria-modal="true"><button class="iconbutton modalclose" id="closeOtp">×</button><div class="modalemblem">◎</div><div class="eyebrow" style="justify-content:center">ATTENDANCE PASS / '+esc(title)+'</div><h2>Your code is ready.</h2><p>Show this six-digit code to an authorized crew admin.</p><div class="code">'+code.split('').map(d=>'<span>'+d+'</span>').join('')+'</div><div class="modalhint">◷ Expires '+esc(new Date(expires).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))+'</div><p>✦ Single-use · Keep your code private</p><button class="primary full" id="doneOtp">Got it ✓</button></div></div>';$('#closeOtp').onclick=()=>$('#modalRoot').innerHTML='';$('#doneOtp').onclick=()=>$('#modalRoot').innerHTML='';$('#otpBackdrop').onclick=e=>{if(e.target.id==='otpBackdrop')$('#modalRoot').innerHTML='';};}
document.addEventListener('click',async e=>{const vote=e.target.closest('[data-vote-id]');if(vote){await action(async()=>{const res=await featureApi('vote','polls',{id:vote.dataset.voteId,choice:vote.dataset.choice});notice(res.message);S.featureItems.polls=await featureApi('list','polls',{});});return;}const results=e.target.closest('[data-poll-results]');if(results){await action(async()=>{const rows=await featureApi('vote-results','polls',{id:results.dataset.pollResults});notice(rows.map(x=>x.choice+': '+x.votes).join(' · ')||'No votes yet');});return;}const mod=e.target.closest('[data-moderate]');if(mod){await action(async()=>{const res=await featureApi('moderate',mod.dataset.feature,{id:mod.dataset.moderate,status:mod.dataset.status});notice(res.message);S.featureItems[mod.dataset.feature]=await featureApi('list',mod.dataset.feature,{});});return;}const delFeature=e.target.closest('[data-feature-delete]');if(delFeature){if(!confirm('Delete this item?'))return;await action(async()=>{const res=await featureApi('delete',delFeature.dataset.feature,{id:delFeature.dataset.featureDelete});notice(res.message);S.featureItems[delFeature.dataset.feature]=await featureApi('list',delFeature.dataset.feature,{});});return;}const openEvent=e.target.closest('[data-open-event]');if(openEvent){S.selectedEvent=openEvent.dataset.openEvent;go('event-detail');return;}const v=e.target.closest('[data-view]');if(v){const target=v.dataset.view;const route=target==='new-event'?'events':target==='new-update'?'updates':target==='achievement-form'?'achievements':target;go(route).then(()=>{const anchor=target==='new-event'?'#eventForm':target==='new-update'?'#updateForm':target==='achievement-form'?'#achievementFormHost':null;if(anchor)$(anchor)?.scrollIntoView({behavior:'smooth',block:'center'});});return;}const r=e.target.closest('[data-register]');if(r){await action(async()=>{let d=await api('register','POST',{eventId:r.dataset.register});notice(d.message);await refresh();});return;}const eq=e.target.closest('[data-event-qr]');if(eq){const event=S.events.find(x=>String(x.id)===String(eq.dataset.eventQr));if(event)showEventQr(event.id,event.title);return;}const o=e.target.closest('[data-otp]');if(o){await action(async()=>{let e0=S.events.find(x=>String(x.id)===String(o.dataset.otp));let d=await api('otp','POST',{eventId:o.dataset.otp});showOtp(d.code,d.expiresAt,e0?.title||'Crew event');notice(d.message);});return;}const s=e.target.closest('[data-scroll]');if(s){$('#'+s.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}if(e.target.closest('[data-clear]')){S.error='';paint();return;}if(e.target.closest('#openQrScanner')){startQr();return;}if(e.target.closest('#closeQrScanner')){stopQr();$('#qrScanner').hidden=true;return;}if(e.target.closest('#finalizeAttendance')){if(!S.rosterEvent||!confirm('Finalize this event attendance? All remaining registered members will be marked absent. This cannot be undone.'))return;await action(async()=>{const r=await api('finalize-attendance','POST',{eventId:S.rosterEvent});S.roster=await api('attendance?eventId='+encodeURIComponent(S.rosterEvent));notice(r.message);});return;}if(e.target.closest('#exportAttendance')){exportAttendance();return;}const del=e.target.closest('[data-delete-event]');if(del){if(!confirm('Delete this event and all its registrations and attendance records? This cannot be undone.'))return;await action(async()=>{const r=await api('delete-event','DELETE',{eventId:del.dataset.deleteEvent});if(S.rosterEvent===del.dataset.deleteEvent){S.roster=null;S.rosterEvent='';}notice(r.message);await refresh();});return;}if(e.target.closest('#logoutProfile')){await auth.signOut();location.replace(window.kcPath('login.html'));return;}const readBtn=e.target.closest('[data-read-notice]');if(readBtn){markRead(readBtn.dataset.readNotice);paint();notice('Notification marked as read.');return;}const noticeItem=e.target.closest('[data-notice-id]');if(noticeItem&&!e.target.closest('button')){markRead(noticeItem.dataset.noticeId);paint();return;}const filterBtn=e.target.closest('[data-notice-filter]');if(filterBtn){S.noticeFilter=filterBtn.dataset.noticeFilter;paint();return;}if(e.target.closest('#markAllRead')){localStorage.setItem(readKey(),JSON.stringify(S.announcements.map(a=>a.id)));paint();notice('All notifications marked as read.');return;}if(e.target.closest('#testNoticeSound')){playNoticeSound();notice('That is your Kinetic Crew alert sound.');return;}if(e.target.closest('#enablePush')){await action(async()=>{const result=await window.kcPush.enable();saveNotificationPrefs({push:true});notice(result.message||'Push alerts enabled on this device.');});return;}});
document.addEventListener('input',e=>{if(e.target.id==='noticeSearch'){S.noticeQuery=e.target.value;const pos=e.target.selectionStart;const app=$('#app');const page=notificationsPage();const start=app.querySelector('.notice-layout');if(start){const temp=document.createElement('div');temp.innerHTML=page;const fresh=temp.querySelector('.notice-layout');start.replaceWith(fresh);const input=$('#noticeSearch');if(input){input.focus();input.setSelectionRange(pos,pos);}}}});
document.addEventListener('change',async e=>{if(e.target.id==='profilePhotoInput'){const file=e.target.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){notice('Choose a JPG, PNG or WebP image under 5 MB.');e.target.value='';return;}try{const ext=file.type==='image/jpeg'?'jpg':file.type.split('/')[1],path=(S.user.auth_id||S.user.id)+'/'+Date.now()+'.'+ext;const {data,error}=await client.storage.from('crew-avatars').upload(path,file,{upsert:true,contentType:file.type});if(error)throw error;S.pendingAvatarUrl=client.storage.from('crew-avatars').getPublicUrl(data.path).data.publicUrl;$('#profilePhotoPreview').src=URL.createObjectURL(file);notice('Photo uploaded. Save your profile to apply it.');}catch(err){notice(err.message||'Photo upload failed. Apply the profile photo storage migration first.');}}else if(e.target.id==='noticeSound'){saveNotificationPrefs({sound:e.target.checked});if(e.target.checked)playNoticeSound();notice(e.target.checked?'In-app sound enabled.':'In-app sound muted.');}});
document.addEventListener('click',async e=>{const save=e.target.closest('.profile-admin-save');if(!save)return;const row=save.closest('[data-profile-row]');await action(async()=>{const {data,error}=await rpc('crew_manage_profile',{p_auth_id:row.dataset.profileRow,p_name:row.querySelector('[name=member_name]').value,p_bio:row.querySelector('[name=member_bio]').value});if(error)throw Error(error.message||'Could not update member profile.');notice('Member profile updated.');await refresh();});});
document.addEventListener('keydown',e=>{const item=e.target.closest('[data-open-event]');if(item&&(e.key==='Enter'||e.key===' ')){e.preventDefault();S.selectedEvent=item.dataset.openEvent;go('event-detail');}}); 
document.addEventListener('submit',async e=>{let f=e.target;const featureFormEl=f.closest('[data-feature-form]');if(featureFormEl){e.preventDefault();const key=featureFormEl.dataset.feature;const d=new FormData(featureFormEl);await action(async()=>{const data={};['amount','category','from_date','to_date','style','media_url'].forEach(k=>{if(d.get(k))data[k]=d.get(k)});if(key==='rehearsals'){data.session_at=new Date(d.get('session_at')).toISOString();data.location=d.get('location')||'';}if(key==='achievements')data.recipient=d.get('recipient')||'';if(key==='leave'&&new Date(data.from_date)>new Date(data.to_date))throw Error('End date must be on or after the start date.');const body=String(d.get('body')||'');const res=await featureApi('create',key,{title:d.get('title'),body,data});notice(res.message);S.featureItems[key]=await featureApi('list',key,{});});return;}if(f.id==='profileForm'){e.preventDefault();const d=new FormData(f);await action(async()=>{const result=await api('profile','PATCH',{name:d.get('name'),bio:d.get('bio'),avatar_url:S.pendingAvatarUrl||S.user.avatar_url||null});S.pendingAvatarUrl=null;S.user={...S.user,...result,name:result.name||d.get('name'),bio:result.bio??d.get('bio')};S.view='profile';notice('Profile updated.');await refresh();});}else if(f.id==='eventForm'){e.preventDefault();let d=new FormData(f);await action(async()=>{let a=await api('events','POST',{title:d.get('title'),location:d.get('location'),description:d.get('description'),starts_at:new Date(d.get('starts_at')).toISOString(),capacity:Number(d.get('capacity'))});S.view='events';notice(a.message);try{const push=await window.kcPush.send('New crew event: '+d.get('title'),d.get('description')||('Event at '+(d.get('location')||'location TBA')),'all');console.info('Push delivery:',push);}catch(pushError){console.warn('Event saved; push delivery failed:',pushError);}await refresh();});}else if(f.id==='updateForm'){e.preventDefault();let d=new FormData(f);await action(async()=>{let a=await api('announcements','POST',{title:d.get('title'),body:d.get('body'),audience:d.get('audience')});S.view='updates';notice(a.message);try{const push=await window.kcPush.send(d.get('title'),d.get('body'),d.get('audience'));console.info('Push delivery:',push);}catch(pushError){console.warn('Announcement saved; push delivery failed:',pushError);}await refresh();});}else if(f.id==='verifyForm'){e.preventDefault();const d=new FormData(f),eventId=String(d.get('eventId')||''),memberEmail=String(d.get('memberEmail')||'').trim(),code=String(d.get('code')||'').trim();if(!eventId||!memberEmail||!/^\\d{6}$/.test(code)){notice('Enter the event, member email and six-digit OTP.');return;}await action(async()=>{const result=await api('verify','POST',{eventId,memberEmail,code});S.rosterEvent=eventId;S.roster=await api('attendance?eventId='+encodeURIComponent(eventId));notice(result.message||'OTP verified. Attendance marked present.');});}});
document.addEventListener('change',async e=>{if(e.target.matches('select[name="eventId"]')){S.rosterEvent=e.target.value;if(!S.rosterEvent){S.roster=null;paint();return;}await action(async()=>{S.roster=await api('attendance?eventId='+encodeURIComponent(S.rosterEvent));});}else if(e.target.id==='rosterSelect'){S.rosterEvent=e.target.value;if(!S.rosterEvent){S.roster=null;paint();return;}await action(async()=>{S.roster=await api('attendance?eventId='+encodeURIComponent(S.rosterEvent));paint();});}else if(e.target.matches('.profile-admin-save')){const row=e.target.closest('[data-profile-row]');await action(async()=>{const {data,error}=await rpc('crew_manage_profile',{p_auth_id:row.dataset.profileRow,p_name:row.querySelector('[name="member_name"]').value,p_bio:row.querySelector('[name="member_bio"]').value});if(error)throw Error(error.message||'Could not update member profile.');notice('Member profile updated.');await refresh();});}else if(e.target.matches('.role-select')){await action(async()=>{let d=await api('role','PATCH',{authId:e.target.dataset.id,role:e.target.value});notice(d.message);await refresh();});}});
$('#app').addEventListener('change',e=>{if(e.target.id==='profilePhotoInput'&&e.target.files?.[0]){const img=$('#profilePhotoPreview');if(img)img.src=URL.createObjectURL(e.target.files[0]);}});$('#logoutProfile')?.addEventListener('click',()=>$('#logout').click());
$('#logout').addEventListener('click',async()=>{try{await auth.signOut();}finally{S.user=null;S.events=[];S.announcements=[];S.members=[];location.replace(window.kcPath('login.html'));}});
$('#updatesTop').addEventListener('click',()=>go('notifications'));
$('#menuToggle').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#navShade').classList.toggle('open');});
$('#navShade').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#navShade').classList.remove('open');});
async function boot(){const loadingStarted=Date.now();const loadingWatch=setTimeout(()=>{const el=$('#app');if(el&&el.textContent.includes('Opening Kinetic Crew')){el.innerHTML='<div class="load-error"><div class="emptyicon">!</div><h2>Still loading your crew</h2><p>The dashboard has not finished loading. Check your connection, then retry.</p><div class="load-actions"><button class="primary" onclick="location.reload()">Reload app</button><button class="outline" id="loadingSignout">Switch account</button></div></div>';$('#loadingSignout')?.addEventListener('click',async()=>{try{await auth?.signOut();}finally{location.replace(window.kcPath('login.html'));}});}},18000);if(!auth){clearTimeout(loadingWatch);$('#app').innerHTML='<div class="load-error"><h2>Sign-in unavailable</h2><p>'+esc(window.KC_CONFIG_ERROR||'Refresh the page and try again.')+'</p><button class="primary" onclick="location.reload()">Retry</button></div>';return;}try{const result=await withTimeout(auth.getSession(),10000,'Authentication is taking too long. Reload the page or sign in again.');const session=result?.data?.session;if(!session||!session.user){location.replace(window.kcPath('login.html'));return;}try{await refresh();}catch(error){if(!restoreOffline(session.user)){throw error;}}}catch(e){S.error=e.message||'Could not load your crew.';$('#app').innerHTML='<div class="load-error"><div class="emptyicon">!</div><h2>Could not load Kinetic Crew</h2><p>'+esc(S.error)+'</p><div class="load-actions"><button class="primary" id="retryBoot">Try again</button><button class="outline" id="switchAccount">Use another account</button></div></div>';$('#retryBoot')?.addEventListener('click',()=>location.reload());$('#switchAccount')?.addEventListener('click',async()=>{try{await auth.signOut();}finally{location.replace(window.kcPath('login.html'));}});}}

// Reliable app reload: refresh live data first; offer a hard reload only if startup is unrecoverable.
const reloadButton=$('#reloadApp');
if(reloadButton)reloadButton.addEventListener('click',async()=>{
 const original=reloadButton.innerHTML;reloadButton.disabled=true;reloadButton.textContent='…';
 try{
  if(!navigator.onLine)throw Error('You are offline. Reconnect to refresh live crew data.');
  const result=await withTimeout(auth.getSession(),10000,'Authentication timed out. Please retry.');
  if(!result?.data?.session?.user){location.replace(window.kcPath('login.html'));return;}
  await refresh();notice('Kinetic Crew refreshed.');
 }catch(error){notice(error.message||'Refresh failed.');}
 finally{reloadButton.disabled=false;reloadButton.innerHTML=original;}
});
window.addEventListener('online',()=>{if(S.user)refresh().then(()=>notice('Connection restored. Crew data refreshed.')).catch(e=>{S.error=e.message||'Could not refresh crew data.';paint();});});
window.addEventListener('offline',()=>{if(S.user){S.offline=true;S.error='You are offline. Showing the last available crew information.';paint();}});
window.addEventListener('error',event=>{console.error('Kinetic Crew runtime error:',event.error||event.message);});
window.addEventListener('unhandledrejection',event=>{console.error('Kinetic Crew async error:',event.reason);});

let installPrompt=null;
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;const b=$('#installApp');if(b)b.hidden=false;});
window.addEventListener('appinstalled',()=>{installPrompt=null;const b=$('#installApp');if(b)b.hidden=true;notice('Kinetic Crew is on your home screen.');});
$('#installApp').addEventListener('click',async()=>{if(!installPrompt){notice('On Android, open Chrome menu and choose Install app or Add to Home screen.');return;}try{await installPrompt.prompt();const result=await installPrompt.userChoice;if(result?.outcome==='accepted')notice('Kinetic Crew is ready on your home screen.');}catch{}installPrompt=null;$('#installApp').hidden=true;});
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register(window.kcPath('sw.js'),{scope:window.kcPath('')}).catch(()=>{}));
boot().finally(()=>{});
})();